export function createQuests(api) {
  const { s, extras, nameOf, say, closeTalk, hud, save, ping, toast, burst, itemName, earn } = api, sq = (s.sq = { active: {}, done: {}, track: "", ...(s.sq || {}) }), x = extras.state, byId = (id) => QUESTS.find((q) => q.id === id);
  const metric = (st) => (st.k === "fish" ? s.caught : st.k === "catch" ? s.fish[st.fish] || 0 : st.k === "forage" ? x.t.forage : st.k === "critter" ? x.t.critter : st.k === "dig" ? s.dig.total : st.k === "kills" ? s.rpg?.kills || 0 : 0);
  const stepOf = (q) => q.steps[sq.active[q.id].step], ready = (st, a) => { if (st.k === "visit") return api.regionNow() === st.region; if (st.k === "trial") return (s.trials[st.id]?.medal || 0) >= st.medal; if (st.k === "delve") return !!s.realm[st.id]?.beat; if (st.k === "bounty") return !!s.bounty?.done?.[st.id]; if (["talk", "bring"].includes(st.k)) return false; return metric(st) - a.base >= st.n; };
  const start = (q) => { sq.active[q.id] = { step: 0, base: metric(q.steps[0]) }; sq.track = q.id; ping("choice"); save(); hud(); };
  const give = (r) => { const out = []; if (r.mon) { s.mon += r.mon; if (api.winter) earn(Math.round(r.mon / 5), { bonus: false }); out.push(`${r.mon} mon`); } if (r.item) { x.bag[r.item[0]] = (x.bag[r.item[0]] || 0) + r.item[1]; out.push(`${r.item[1]} ${itemName(r.item[0])}`); } return out.join(", "); };
  function finish(q, person, pick) { const base = give(q.reward), extra = pick ? give(pick[2]) : ""; delete sq.active[q.id]; sq.done[q.id] = pick ? pick[0] : 1; if (sq.track === q.id) sq.track = Object.keys(sq.active)[0] || ""; save(); hud(); ping("done"); burst({ x: s.x, y: s.y }, 34); const n = Object.keys(sq.done).length; let bonus = ""; if (n === QUESTS.length) { s.mon += 1500; if (!s.hats.includes("neighbour")) s.hats.push("neighbour"); s.hat = "neighbour"; bonus = " That's every favour in the country. The Good Neighbour's bonnet is yours, plus 1500 mon."; save(); hud(); } say(person, `${pick ? pick[1] : q.end} (Quest complete: ${[base, extra].filter(Boolean).join(", ")}. ${n} of ${QUESTS.length} done.)${bonus}`); }
  function next(q, person) { const a = sq.active[q.id]; a.step++; if (a.step >= q.steps.length) { if (q.choices) return say(person, "What do you say?", q.choices.map((c) => [c[0], () => finish(q, person, c), "q"])); return finish(q, person); } a.base = metric(q.steps[a.step]); ping("choice"); save(); hud(); closeTalk(); toast(`${q.title}: ${goal(q)}`); }
  function goal(q) { const a = sq.active[q.id], st = stepOf(q); if (!st) return "Finish the conversation"; if (st.k === "talk") return `Talk to ${nameOf(st.who)}`; if (st.k === "bring") return `Bring ${st.n} ${itemName(st.item)} to ${nameOf(st.who)} (${x.bag[st.item] || 0}/${st.n})`; if (st.n) return `${st.goal} (${Math.min(st.n, metric(st) - a.base)}/${st.n})`; return st.goal; }
  function run(q, person) { const st = stepOf(q); if (!st) return say(person, "What do you say?", (q.choices || []).map((c) => [c[0], () => finish(q, person, c), "q"])); if (st.k === "bring" && (x.bag[st.item] || 0) < st.n) return say(person, `Still need ${st.n} ${itemName(st.item)}. You've got ${x.bag[st.item] || 0}.`, [["Back", () => closeTalk(), "q"]]); say(person, st.say, [[st.btn, () => { if (st.k === "bring") x.bag[st.item] -= st.n; next(q, person); }, "q"]]); }
  const offer = (q, person) => say(person, q.ask, [["I'll do it", () => { start(q); closeTalk(); toast(`New quest: ${q.title}`); }, "q"], ["Not right now", () => closeTalk(), "q"]]);
  const lastWho = (q) => [...q.steps].reverse().find((st) => st.who)?.who;
  const btns = (person) => { const id = person.id, out = []; for (const q of QUESTS) { if (sq.active[q.id]) { const st = stepOf(q); if ((st && ["talk", "bring"].includes(st.k) && st.who === id) || (!st && lastWho(q) === id)) out.push([`Quest: ${q.title}`, () => run(q, person), "q"]); } else if (!sq.done[q.id] && q.giver === id) out.push([`New quest: ${q.title}`, () => offer(q, person), "q"]); } return out.slice(0, 2); };
  const mark = (id) => { for (const q of QUESTS) if (sq.active[q.id]) { const st = stepOf(q); if (!st && lastWho(q) === id) return "ready"; if (st && ["talk", "bring"].includes(st.k) && st.who === id && (st.k === "talk" || (x.bag[st.item] || 0) >= st.n)) return "ready"; } return QUESTS.some((q) => q.giver === id && !sq.active[q.id] && !sq.done[q.id]) ? "new" : ""; };
  function tick() { for (const q of QUESTS) { const a = sq.active[q.id]; if (!a) continue; let guard = 0; while (guard++ < q.steps.length) { const st = q.steps[a.step]; if (!st || !ready(st, a)) break; a.step++; a.base = q.steps[a.step] ? metric(q.steps[a.step]) : 0; ping("done"); save(); toast(`${q.title}: ${goal(q)}`); hud(); } } }
  const tracked = () => { const id = sq.track && sq.active[sq.track] ? sq.track : Object.keys(sq.active)[0]; const q = id && byId(id); return q ? `${q.title}: ${goal(q)}` : ""; };
  const page = () => ({ act: QUESTS.filter((q) => sq.active[q.id]), open: QUESTS.filter((q) => !sq.active[q.id] && !sq.done[q.id]), done: QUESTS.filter((q) => sq.done[q.id]), goal, track: sq.track });
  return { btns, mark, tick, tracked, page, state: sq, setTrack: (id) => { sq.track = id; save(); hud(); }, start, run, offer, byId };
}
